    {
      "chord_quality": "dom7",
      "function_role": "outside-line-superimposition",
      "narrative": "For a D7 chord, Benson prescribes playing small A7 ideas in the middle of the line to create an outside effect -- the First GB Chord Transition technique. The substitution chord is superimposed momentarily within the single-note line, not comped, to generate harmonic color. Chapter 9, p. 26.",
      "source_principle_ids": [
        "benson:method-vol-6-giant-lines:outside-substitution:outside-entry-superimpose"
