      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7",
      "function_role": "outside-line-duration-limit",
      "narrative": "Do not stay on the A7 substitution idea too long over D7 -- exceeding the effective threshold destroys the outside effect and tips the line into mere dissonance rather than colorful tension. The outside superimposition is a flash move, not a sustained region. Chapter 9, p. 26.",
      "source_principle_ids": [
        "benson:method-vol-6-giant-lines:outside-substitution:outside-duration-limit"
