      ],
      "granularity_level": "f",
      "granularity_name": "rhythmic-placement"
    },
    {
      "chord_quality": "dom7",
      "function_role": "v7-i-mini-cadence-inside-line",
      "narrative": "The Second GB Chord Transition prescribes embedding a mini V7-I cadence within a single-line idea over D7 -- specifically D7 leading to G major -- as an additional outside device distinct from the A7 superimposition. The relative minor (Em for G) then unlocks a further set of dominant scale options for the line. Chapter 9, p. 26.",
      "source_principle_ids": [
        "benson:method-vol-6-giant-lines:outside-substitution:v7-i-cadence-superimpose"
      ],
      "source_work_id": "method-vol-6-giant-lines",
      "references": [
        {
          "source": "method-vol-6-giant-lines",
          "citation": "chapter 9, p. 26"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "i",
      "granularity_name": "other"
    },
    {
      "chord_quality": "dom7",
      "function_role": "outside-line-ending-note-rule",
      "narrative": "Any single-line idea -- inside or outside -- constructed over D7 must end on a chord tone of D7. This Ending Note Rule applies universally to all the outside-effect lines in the chapter; harmonic coherence is restored at the conclusion of each line regardless of how far outside it travels. Chapter 9, p. 26.",
      "source_principle_ids": [
        "benson:method-vol-6-giant-lines:outside-substitution:resolution-note-chord-tone-rule"
      ],
      "source_work_id": "method-vol-6-giant-lines",
