      "granularity_level": "g",
      "granularity_name": "voice-leading"
    },
    {
      "chord_quality": "dom7",
      "function_role": "mixolydian-family-b7-outside-device",
      "narrative": "Because D Mixolydian derives from the Em chord family, Benson prescribes using B7 ideas leading to Em as a 'very beautiful' outside device over a single D7. The justification is modal-family coherence: the Mixolydian mode's parent chord family supplies the secondary dominant that generates the outside color. Chapter 9, p. 31.",
      "source_principle_ids": [
        "benson:method-vol-6-giant-lines:outside-substitution:modal-family-outside-entry"
      ],
      "source_work_id": "method-vol-6-giant-lines",
      "references": [
        {
          "source": "method-vol-6-giant-lines",
          "citation": "chapter 9, p. 31"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "min7",
      "function_role": "static-giant-line-inside-and-outside",
      "narrative": "For Dm7 in a static (one-chord vamp) context, Benson organizes the melodic vocabulary into both 'inside' and 'outside' categories, presenting worked examples of each as Giant Lines. The student is expected to practice both categories systematically over the sustained Dm7 before moving to active (changing-chord) contexts. Chapter 11, pp. 60-90.",
      "source_principle_ids": [
        "benson:method-vol-6-giant-lines:outside-substitution:outside-entry-superimpose"
      ],
      "source_work_id": "method-vol-6-giant-lines",
