      "granularity_name": "other"
    },
    {
      "chord_quality": "dom7",
      "function_role": "active-line-major7-superimposition-for-minor-resolution",
      "narrative": "When a dominant 7th (A7) resolves to a minor tonic (Dm7), Benson prescribes using major-7th superimposed ideas over A7 to strengthen the pull toward Dm7. These same major-7th superimposed options over C7 leading to Fmaj7 may sound too tense or even incorrect, and are not recommended in that context. Chapter 13, p. 77.",
      "source_principle_ids": [
        "benson:method-vol-6-giant-lines:outside-substitution:major7-superimpose-for-minor-resolution"
      ],
      "source_work_id": "method-vol-6-giant-lines",
      "references": [
        {
          "source": "method-vol-6-giant-lines",
          "citation": "chapter 13, p. 77"
        }
      ],
      "provenance": "extracted",
      "cross_ref": [
        "active-line-major7-superimposition-avoid-major-resolution-dom7"
      ],
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7",
      "function_role": "active-line-major7-superimposition-avoid-major-resolution",
      "narrative": "Do not apply major-7th superimposed ideas over C7 when it leads to Fmaj7 -- these options may sound too tense or even incorrect in that cadential context. The major-7th superimposition is prescribed for dominant-to-minor resolutions (A7 -> Dm7) only, not for dominant-to-major resolutions (C7 -> Fmaj7). Chapter 13, p. 77.",
      "source_principle_ids": [
        "benson:method-vol-6-giant-lines:outside-substitution:major7-superimpose-for-minor-resolution"
